import json, re, random, sys, os, chess
RE = json.load(open(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 're.json')))

def run(fen):
    for p, r in RE:
        fen = re.sub(p, r, fen)
    return fen.split("\n")

ex = "rnb1k1nr/p2p1ppp/3B4/1p1NPN1P/6P1/3P1Q2/P1P5/q4Kb1 w kq - 0 1"
exp = "rnb1k1nr/p2p1ppp/3B4/1p1NPN1P/6P1/3P1Q2/P1P1K3/q5b1 b kq - 0 0\nrnb1k1nr/p2p1ppp/3B4/1p1NPN1P/6P1/3P1Q2/P1P3K1/q5b1 b kq - 0 0\nrnb1k1nr/p2p1ppp/3B4/1p1NPN1P/6P1/3P4/P1P5/q2Q1Kb1 b kq - 0 0"
got = run(ex)
assert sorted(got) == sorted(exp.split("\n")), got

def check(fen):
    ours = [" ".join(x.split(" ")[:-2]) for x in run(fen)]
    b = chess.Board(fen)
    want = set()
    for m in b.legal_moves:
        if m.promotion and m.promotion != chess.QUEEN:
            continue
        c = b.copy(); c.push(m)
        want.add(" ".join(c.fen().split(" ")[:-2]))
    for x in ours:
        if not (x in want or x.rpartition(" ")[0] + " -" in want):
            print("BAD", fen, x, sorted(want)); return False
    if len(ours) != len(want):
        print("COUNT", fen, len(ours), len(want), sorted(set(ours) ^ want)); return False
    return True

random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
n = 0
for g in range(int(sys.argv[2]) if len(sys.argv) > 2 else 300):
    b = chess.Board()
    while not b.is_game_over():
        if b.turn == chess.WHITE:
            if not check(b.fen()):
                sys.exit(1)
            n += 1
        moves = list(b.legal_moves)
        # bias towards captures/pawn moves for variety
        b.push(random.choice(moves))
print("ok", n)
